// Element reference data for the Chemistry playground.
//
// Masses are IUPAC conventional/abridged standard atomic weights (mass number
// of the longest-lived isotope for elements with no stable isotope).
// Electron configurations are generated by the Madelung (Aufbau) rule with the
// well-known ground-state exceptions listed below; those for Z > 103 are
// predictions, not measurements.
// Oxidation states: `common` = the states you meet in an introductory/inorganic
// course; `other` = real but less frequent states. This is a teaching table,
// not an exhaustive survey.

export type Category =
  | 'alkali' | 'alkaline' | 'transition' | 'post-transition' | 'metalloid'
  | 'nonmetal' | 'halogen' | 'noble' | 'lanthanide' | 'actinide' | 'unknown';

export interface Element {
  z: number;
  symbol: string;
  name: string;
  mass: number;
  group: number | null; // null for lanthanides/actinides in the main grid
  period: number;
  category: Category;
  config: string;
  en: number | null; // Pauling electronegativity
  common: number[];
  other: number[];
  predicted: boolean; // Z > 103: properties are predicted, not measured
}

// symbol, name, mass, category, Pauling EN, common OS, other OS
type Row = [string, string, number, Category, number | null, number[], number[]];

