// ── Electron configurations ────────────────────────────────────────────────
const ORDER: [number, 's' | 'p' | 'd' | 'f'][] = [];
(() => {
  // Madelung: fill by n+l, then by n.
  const L = { s: 0, p: 1, d: 2, f: 3 } as const;
  const cells: { n: number; l: 's' | 'p' | 'd' | 'f' }[] = [];
  for (let n = 1; n <= 8; n++) for (const l of ['s', 'p', 'd', 'f'] as const) {
    if (L[l] < n) cells.push({ n, l });
  }
  cells.sort((a, b) => (a.n + L[a.l]) - (b.n + L[b.l]) || a.n - b.n);
  for (const c of cells) ORDER.push([c.n, c.l]);
})();
const CAP = { s: 2, p: 6, d: 10, f: 14 } as const;
const NOBLE: [number, string][] = [[86, 'Rn'], [54, 'Xe'], [36, 'Kr'], [18, 'Ar'], [10, 'Ne'], [2, 'He']];

// Measured ground-state exceptions to the Madelung order (NIST), written as
// the part after the noble-gas core.
const EXCEPTIONS: Record<string, string> = {
  Cr: '[Ar] 3d5 4s1', Cu: '[Ar] 3d10 4s1',
  Nb: '[Kr] 4d4 5s1', Mo: '[Kr] 4d5 5s1', Ru: '[Kr] 4d7 5s1', Rh: '[Kr] 4d8 5s1',
  Pd: '[Kr] 4d10', Ag: '[Kr] 4d10 5s1',
  La: '[Xe] 5d1 6s2', Ce: '[Xe] 4f1 5d1 6s2', Gd: '[Xe] 4f7 5d1 6s2',
  Pt: '[Xe] 4f14 5d9 6s1', Au: '[Xe] 4f14 5d10 6s1',
  Ac: '[Rn] 6d1 7s2', Th: '[Rn] 6d2 7s2', Pa: '[Rn] 5f2 6d1 7s2',
  U: '[Rn] 5f3 6d1 7s2', Np: '[Rn] 5f4 6d1 7s2', Cm: '[Rn] 5f7 6d1 7s2',
  Lr: '[Rn] 5f14 7s2 7p1',
};

function superscript(n: number): string {
  return String(n).split('').map(d => '⁰¹²³⁴⁵⁶⁷⁸⁹'[Number(d)]).join('');
}

function buildConfig(z: number, symbol: string): string {
  const ex = EXCEPTIONS[symbol];
  const raw = ex ?? (() => {
    let left = z;
    const filled: string[] = [];
    for (const [n, l] of ORDER) {
      if (left <= 0) break;
      const k = Math.min(CAP[l], left);
      filled.push(`${n}${l}${k}`);
      left -= k;
    }
    // Compress with a noble-gas core.
    const core = NOBLE.find(([nz]) => nz < z);
    if (!core) return filled.join(' ');
    let skipped = 0, i = 0;
    while (i < filled.length && skipped < core[0]) {
      skipped += Number(filled[i].slice(2));
      i++;
    }
    const rest = filled.slice(i).sort((a, b) => {
      const key = (s: string) => Number(s[0]) * 10 + 'spdf'.indexOf(s[1]);
      return key(a) - key(b);
    });
    return `[${core[1]}] ${rest.join(' ')}`;
  })();
  // Pretty-print exponents as superscripts.
  return raw.replace(/([spdf])(\d+)/g, (_, l: string, k: string) => `${l}${superscript(Number(k))}`);
}

// ── Grid position (18-column table, with f-block rows below) ────────────────
function layout(z: number): { group: number | null; period: number } {
  if (z === 1) return { group: 1, period: 1 };
  if (z === 2) return { group: 18, period: 1 };
  if (z <= 4) return { group: z - 2, period: 2 };
  if (z <= 10) return { group: z + 8, period: 2 };
  if (z <= 12) return { group: z - 10, period: 3 };
  if (z <= 18) return { group: z, period: 3 };
  if (z <= 36) return { group: z - 18, period: 4 };
  if (z <= 54) return { group: z - 36, period: 5 };
  if (z <= 56) return { group: z - 54, period: 6 };
  if (z <= 71) return { group: null, period: 6 }; // La–Lu
  if (z <= 86) return { group: z - 68, period: 6 };
  if (z <= 88) return { group: z - 86, period: 7 };
  if (z <= 103) return { group: null, period: 7 }; // Ac–Lr
  return { group: z - 100, period: 7 };
}

export const ELEMENTS: Element[] = ROWS.map((r, i) => {
  const z = i + 1;
  const { group, period } = layout(z);
  return {
    z, symbol: r[0], name: r[1], mass: r[2], group, period,
    category: r[3], en: r[4], common: r[5], other: r[6],
    config: buildConfig(z, r[0]),
    predicted: z > 103,
  };
});

export const BY_SYMBOL: Record<string, Element> = Object.fromEntries(ELEMENTS.map(e => [e.symbol, e]));

